pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: caller address and a block timestamp (as uint256) to attempt calling fallback
    function testFuzz_property(address caller, uint256 ts) public {
        // admissible: caller must be non-zero
        vm.assume(caller != address(0));
        // keep timestamp in reasonable uint range (but wide)
        ts = bound(ts, 1, type(uint256).max - 1);

        // ensure the caller has funds to send 10 ether
        vm.deal(caller, 20 ether);

        // 1) first call: advance to timestamp ts and have caller send 10 ether
        vm.warp(ts);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // record pastBlockTime after first call
        uint256 afterFirst = c.pastBlockTime();

        // 2) second call: do not advance time (same ts) and call again with 10 ether
        vm.warp(ts); // same timestamp as before
        vm.prank(caller);
        c.f{value: 10 ether}();

        // The general property: in the reference, pastBlockTime is only updated when
        // block.timestamp > previous pastBlockTime, so a second call in the same block
        // (same timestamp) must NOT change pastBlockTime. We assert that here.
        assertTrue(c.pastBlockTime() == afterFirst);
    }
}

