pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and an initial block timestamp offset to make the scenario general
    function testFuzz_property(address caller, uint256 initialTimestampOffset) public {
        // keep caller non-zero
        vm.assume(caller != address(0));

        // bound the timestamp offset to a reasonable recent range to avoid overflow/edge cases
        uint256 off = bound(initialTimestampOffset, 0, 1 days);

        // give the caller enough ETH and ensure the test contract has funds to send
        vm.deal(caller, 20 ether);
        vm.deal(address(this), 20 ether);

        // set a controlled block timestamp
        uint256 base = block.timestamp + off;
        vm.warp(base);

        // first call: must send exactly 10 ether per contract requirement
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("0x");
        // first call should succeed on the reference contract (and also on mutant for this input)
        vm.assume(ok1);

        // record pastBlockTime after first call via the autogenerated getter
        uint256 after1 = c.pastBlockTime();

        // Now, without advancing time (same block timestamp), send another 10 ether from same caller
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("0x");
        // call itself should succeed as well (both contracts accept 10 ether)
        vm.assume(ok2);

        uint256 after2 = c.pastBlockTime();

        // General rule (single assertion): In the correct contract, if timestamp did NOT advance between two valid fallback calls,
        // pastBlockTime must remain equal (i.e., second call does not update it). The mutant removes the time check and may change it.
        assertTrue(after2 == after1);
    }
}

