    function testFuzz_property(address caller, uint256 warpTo) public {
        // keep caller as a non-zero address
        vm.assume(caller != address(0));
        // bound warpTo to a reasonable future range to avoid VM overflow and ensure progress
        uint256 t = bound(warpTo, block.timestamp + 1, block.timestamp + 1 days);

        // ensure caller has funds to send 10 ether
        vm.deal(caller, 20 ether);

        // ensure time advances so require(block.timestamp > pastBlockTime) passes (pastBlockTime starts 0)
        vm.warp(t);

        // perform the payable fallback call sending exactly 10 ether as that is required
        vm.prank(caller);
        c.f{value: 10 ether}();

