    function testFuzz_property(address actor, uint256 ts) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound timestamp to a reasonable future range to avoid underflow of require(block.timestamp > pastBlockTime)
        ts = bound(ts, 1, type(uint64).max);

        // give actor funds and set timestamp
        vm.deal(actor, 20 ether);
        vm.warp(ts);

        // perform the payable fallback call with exactly 10 ether from actor
        vm.prank(actor);
        bool ok;
        try c.call{value: 10 ether}("") {
